/// <summary>
/// Extension of ReqItemTable form
/// </summary>
[ExtensionOf(formStr(ReqItemTable))]
final class METReqItemTableForm_Extension
{
}

Method.Source:
/// <summary>
/// Set form control method is called from active method to get current value
/// </summary>
public void setFormControls()
{
    next setFormControls();

    FormRun formRun = this as FormRun;

    FormDataSource formDatasource = formRun.dataSource(tableStr(ReqItemTable));
    ReqItemTable reqItemTable = formDatasource.cursor();

    FormGroupControl formGroupControl = formRun.design().controlName(formControlStr(ReqItemTable, METIntercompanySourced));

    formGroupControl.optionValue(reqItemTable.METInterCompanySourced);        

}

/// <summary>
/// Enable disable fields
/// </summary>
void enableFields()
{
    FormRun formRun = this as FormRun;

    FormDataSource formDatasource = formRun.dataSource(tableStr(ReqItemTable));
    ReqItemTable reqItemTable = formDatasource.cursor();
    FormGroupControl formGroupControl = formRun.design().controlName(formControlStr(ReqItemTable, METIntercompanySourced));

    next enableFields();

    formDatasource.object(fieldnum(ReqItemTable, METInterCompanySourced)).allowEdit(reqItemTable.ReqPOType == ReqPOType::Purch ? true : false);
    formGroupControl.allowEdit(reqItemTable.ReqPOType == ReqPOType::Purch ? true : false);
    formGroupControl.enabled(reqItemTable.ReqPOType == ReqPOType::Purch ? true : false);
}
